fn count7(x: u8) -> u8 {
    // Convert the number to a string in base 10
    let digits = x.to_string();
    
    // Count the occurrences of '7' in the string representation
    digits.chars().filter(|&c| c == '7').count() as u8
}

fn main() {
    // Example usage
    let number: u8 = 177;
    let count = count7(number);
    println!("The number of 7s in {} is {}", number, count);
}